-- Victor Vasquez (profileID=22) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Victor Vasquez phrasings

SELECT p.argumentID, p.phrasingID, 22, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 22
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 22 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=22 AND targArgID IN (90,94,101,103,104,107,108,110,118,136,145,148,169,175,217,218,219,322,323,349,350,367,400,401,481,482,483,484,485,486,498,499,500,501,502,539,546,547,548,560,561,574,590,603,1197,1319,1320);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 22
SET pe.active = o.acceptance
WHERE pe.profileID = 22;

SELECT 'Done: endorsements for profileID=22' AS status;